<?php
namespace App\Core; use PDO;
final class Auth { public static function start():void{if(session_status()!==PHP_SESSION_ACTIVE)session_start();} public static function user():?array{self::start();return $_SESSION['user']??null;} public static function login(PDO $db,string $email,string $password):bool{$q=$db->prepare("SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.email=? AND u.status='active' LIMIT 1");$q->execute([$email]);$u=$q->fetch();if(!$u||!password_verify($password,$u['password_hash']))return false;self::start();$_SESSION['user']=$u;return true;} public static function logout():void{self::start();$_SESSION=[];session_destroy();} public static function requireLogin():void{if(!self::user()){header('Location: /?page=login');exit;}}}
